import http from 'node:http';import fs from 'node:fs';import path from 'node:path';import os from 'node:os';import crypto from 'node:crypto';import {fileURLToPath} from 'node:url';
import {defaults,cleanConfig,privateIP,selected,payload,validatePatch,captureScene,scenePayload} from './engine.mjs';
import {LIMIT,atomicJSON,readJSON,updaterInfo,setSource,fetchUpdate,installBundle,rollback} from './updater.mjs';
const ROOT=path.dirname(fileURLToPath(import.meta.url)),PKG=readJSON(path.join(ROOT,'package.json'),{}),PORT=Number(process.env.TUBEROOM_PORT||8788),TEST=process.env.TUBEROOM_TEST==='1';
const DATA=process.env.TUBEROOM_DATA||path.join(os.homedir(),'Library','Application Support','TubeRoom');fs.mkdirSync(DATA,{recursive:true});
if(PKG.updateSource&&!fs.existsSync(path.join(DATA,'update-source.json')))setSource(DATA,PKG.updateSource);
// Keep v1 preferences/session files intact so app rollback remains possible.
let config=cleanConfig(readJSON(path.join(DATA,'settings-v3.json'),readJSON(path.join(DATA,'settings.json'),defaults())),defaults(),TEST);
let scenes=readJSON(path.join(DATA,'scenes-v3.json'),[]),devices={},busy=false,restarting=false,pendingUpdate=null;
const token=crypto.randomBytes(24).toString('hex'),file=(n)=>path.join(DATA,n),save=()=>atomicJSON(file('settings-v3.json'),config);
// The original Mac launcher looks for the effects key when detecting an already-running app.
const state=()=>({version:PKG.version,pid:process.pid,effects:[],config,devices,busy,scenes:scenes.map(({id,name,bars})=>({id,name,ids:bars.map(b=>b.id)})),token});
const connected=()=>config.tubes.filter(t=>t.ip&&t.enabled);
async function wled(ip,route='/json',data,timeout=2800){
 if(!privateIP(ip)&&!(TEST&&/^127\.0\.0\.[1-5]$/.test(ip)))throw Error('A local IPv4 address is required.');
 const url=TEST?`http://127.0.0.1:${process.env.TUBEROOM_WLED_PORT}${route}`:`http://${ip}${route}`;
 const r=await fetch(url,{method:data?'POST':'GET',redirect:'error',headers:{...(data?{'Content-Type':'application/json'}:{}),...(TEST?{'X-TubeRoom-Test-IP':ip}:{})},body:data?JSON.stringify(data):undefined,signal:AbortSignal.timeout(timeout)});
 if(!r.ok)throw Error('WLED returned HTTP '+r.status);const j=await r.json();if(j.error)throw Error('WLED rejected the command ('+j.error+').');return j;
}
async function probe(t,full=false){
 try{const old=devices[t.id],j=await wled(t.ip,full||!old?.ok?'/json':'/json/state');
  if(full||!old?.ok){if(!j.state||!Array.isArray(j.effects)||!j.effects.length||!Array.isArray(j.palettes)||!Number.isInteger(j.info?.leds?.count))throw Error('No valid WLED data. Check the IP.');let fxdata=[];try{fxdata=await wled(t.ip,'/json/fxdata',undefined,1200);}catch{}
   devices[t.id]={id:t.id,ip:t.ip,name:t.name,ok:true,version:j.info.ver,count:j.info.leds.count,effects:j.effects,palettes:j.palettes,fxdata:Array.isArray(fxdata)?fxdata:[],state:j.state,at:Date.now()};
  }else{if(!Array.isArray(j.seg))throw Error('Invalid WLED state.');devices[t.id]={...old,name:t.name,state:j,at:Date.now(),ok:true};}return devices[t.id];
 }catch(e){devices[t.id]={id:t.id,ip:t.ip,name:t.name,ok:false,error:e.message,at:Date.now()};throw Error(`${t.name}: ${e.message}`);}
}
async function refresh(full=false){await Promise.allSettled(connected().map(t=>probe(t,full)));}
async function locked(fn){if(busy)throw Error('Another change is in progress. Try again.');busy=true;try{return await fn();}finally{busy=false;}}
async function dispatch(bars,make){
 // Read every target and validate all commands before sending any light changes.
 const reads=await Promise.allSettled(bars.map(t=>probe(t,true)));const failed=reads.filter(r=>r.status==='rejected');if(failed.length)throw Error('Nothing changed. '+failed.map(r=>r.reason.message).join(' · '));
 const commands=bars.map(t=>({t,p:make(t,devices[t.id])}));
 const results=await Promise.allSettled(commands.map(({t,p})=>wled(t.ip,'/json/state',p)));
 await Promise.allSettled(bars.map(t=>probe(t)));
 return {results:results.map((r,i)=>({id:bars[i].id,name:bars[i].name,ok:r.status==='fulfilled',error:r.status==='rejected'?r.reason.message:undefined})),...state()};
}
async function blackout(){
 const bars=connected();const results=await Promise.allSettled(bars.map(t=>wled(t.ip,'/json/state',{on:false,transition:0,udpn:{send:false,rgrp:0,nn:true}})));
 await Promise.allSettled(bars.map(t=>probe(t)));return {...state(),results:results.map((r,i)=>({id:bars[i].id,name:bars[i].name,ok:r.status==='fulfilled',error:r.status==='rejected'?r.reason.message:undefined}))};
}
function networks(){return Object.values(os.networkInterfaces()).flat().filter(x=>x?.family==='IPv4'&&!x.internal&&privateIP(x.address)).map(x=>x.address.split('.').slice(0,3).join('.')).filter((x,i,a)=>a.indexOf(x)===i);}
async function scan(prefix){if(!networks().includes(prefix))throw Error('Choose a network connected to this Mac.');let next=1;const found=[];await Promise.all(Array.from({length:20},async()=>{while(next<255){const ip=prefix+'.'+next++;try{const j=await wled(ip,'/json/info',undefined,550);if(Number.isInteger(j.leds?.count))found.push({ip,name:String(j.name||'WLED'),count:j.leds.count});}catch{}}}));return {found};}
function reply(res,code,value){res.writeHead(code,{'Content-Type':'application/json','Cache-Control':'no-store'});res.end(JSON.stringify(value));}
async function body(req,limit){let s='';for await(const chunk of req){s+=chunk;if(Buffer.byteLength(s)>limit)throw Error('Request too large.');}return s?JSON.parse(s):{};}
const server=http.createServer(async(req,res)=>{
 const hosts=[`127.0.0.1:${PORT}`,`localhost:${PORT}`];if(!hosts.includes(req.headers.host)||req.headers.origin&&!hosts.some(h=>req.headers.origin===`http://${h}`)){reply(res,403,{error:'Local access only.'});return;}
 const url=new URL(req.url,`http://127.0.0.1:${PORT}`);
 try{
  if(req.method==='GET'&&url.pathname==='/api/state'){reply(res,200,state());return;}
  if(req.method==='POST'&&url.pathname.startsWith('/api/')){
   if(req.headers['x-tuberoom-token']!==token)throw Error('Refresh this page to reconnect.');if(restarting)throw Error('TubeRoom is restarting.');
   const b=await body(req,url.pathname==='/api/update/install'?LIMIT+1024:64000);let result;
   switch(url.pathname){
    case '/api/config':result=await locked(async()=>{const next=cleanConfig(b,config,TEST);for(const t of next.tubes)if(t.ip!==config.tubes[t.id].ip||t.enabled!==config.tubes[t.id].enabled)delete devices[t.id];config=next;save();return state();});break;
    case '/api/refresh':result=await locked(async()=>{await refresh(!!b.full);return state();});break;
    case '/api/control':validatePatch(b.patch);result=await locked(()=>dispatch(selected(config,b.ids),(_,d)=>payload(b.patch,d)));break;
    case '/api/blackout':result=await locked(blackout);break;
    case '/api/preview':{const results=await Promise.allSettled(connected().map(async t=>{const p=await wled(t.ip,'/json/live',undefined,1000);if(!Array.isArray(p.leds)||p.leds.length>2000||!p.leds.every(c=>typeof c==='string'&&/^[\da-f]{6}$/i.test(c)))throw Error('Preview not supported');return {id:t.id,leds:p.leds,at:Date.now()};}));result={previews:results.filter(r=>r.status==='fulfilled').map(r=>r.value)};break;}
    case '/api/networks':result={networks:networks()};break;
    case '/api/scan':result=await locked(()=>scan(String(b.prefix||'')));break;
    case '/api/scene/save':result=await locked(async()=>{const bars=selected(config,b.ids),name=String(b.name||'').trim().slice(0,36);if(!name)throw Error('Name this scene.');if(scenes.length>=12)throw Error('You can save 12 scenes. Remove one first.');await Promise.all(bars.map(t=>probe(t,true)));scenes.push({id:crypto.randomUUID(),name,bars:bars.map(t=>({id:t.id,...captureScene(devices[t.id])}))});atomicJSON(file('scenes-v3.json'),scenes);return state();});break;
    case '/api/scene/apply':result=await locked(async()=>{const scene=scenes.find(s=>s.id===b.id);if(!scene)throw Error('Scene not found.');return dispatch(selected(config,scene.bars.map(x=>x.id)),(t,d)=>scenePayload(scene.bars.find(x=>x.id===t.id),d));});break;
    case '/api/scene/delete':result=await locked(async()=>{scenes=scenes.filter(s=>s.id!==b.id);atomicJSON(file('scenes-v3.json'),scenes);return state();});break;
    case '/api/update/status':result=updaterInfo(DATA,PKG.version);break;
    case '/api/update/source':setSource(DATA,String(b.url||''));pendingUpdate=null;result=updaterInfo(DATA,PKG.version);break;
    case '/api/update/check':{const u=await fetchUpdate(DATA,PKG.version);pendingUpdate=u.available?u.bundle:null;result={available:u.available,version:u.version,notes:u.notes};break;}
    case '/api/update/install':case '/api/update/rollback':{
     if(process.env.TUBEROOM_MANAGED!=='1')throw Error('Reopen with Start-TubeRoom.command to update.');if(busy)throw Error('Wait for the current command.');
     if(url.pathname.endsWith('install')){const bundle=b.bundle||pendingUpdate;if(!bundle)throw Error('Check for updates or choose an update file.');result=installBundle(DATA,bundle,PKG.version);}else result=rollback(DATA);
     restarting=true;result.restarting=true;setTimeout(()=>shutdown(75),300);break;}
    default:reply(res,404,{error:'Unknown action.'});return;
   }if(result&&'busy'in result)result.busy=busy;reply(res,200,result);return;
  }
  const fileName={'/':'index.html','/app.js':'app.js','/style.css':'style.css'}[url.pathname];if(req.method!=='GET'||!fileName){reply(res,404,{error:'Not found.'});return;}
  res.writeHead(200,{'Content-Type':fileName.endsWith('.css')?'text/css':fileName.endsWith('.js')?'text/javascript':'text/html','Cache-Control':'no-store','X-Content-Type-Options':'nosniff','Content-Security-Policy':"default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; connect-src 'self'; img-src 'self' data:; frame-ancestors 'none'"});fs.createReadStream(path.join(ROOT,'public',fileName)).pipe(res);
 }catch(e){if(!res.headersSent)reply(res,400,{error:e.message});else res.end();}
});
server.on('error',e=>{console.error(e.message);process.exit(1);});server.listen(PORT,'127.0.0.1',()=>console.log(`TubeRoom v3 · http://127.0.0.1:${PORT}\nNative WLED effects continue after closing this app.`));
function shutdown(code=0){save();server.close();process.exit(code);}process.on('SIGINT',()=>shutdown());process.on('SIGTERM',()=>shutdown());

// WLED is the renderer. TubeRoom only sends explicit native control changes.
export function defaults(){return {version:3,groups:[{name:'Group A'},{name:'Group B'}],tubes:Array.from({length:5},(_,id)=>({id,name:`Bar ${id+1}`,ip:'',enabled:true,group:id<3?0:1}))};}
export function privateIP(ip){const a=String(ip).split('.');return a.length===4&&a.every(x=>/^\d{1,3}$/.test(x)&&+x<=255)&&(+a[0]===10||(+a[0]===192&&+a[1]===168)||(+a[0]===172&&+a[1]>=16&&+a[1]<=31));}
export function cleanConfig(input={},base=defaults(),test=false){
 const c=structuredClone(base);c.version=3;
 if(input.groups){if(!Array.isArray(input.groups)||input.groups.length!==2)throw Error('Use two groups.');c.groups=input.groups.map((g,i)=>({name:String(g.name||`Group ${i?'B':'A'}`).trim().slice(0,24)}));}
 if(input.tubes){if(!Array.isArray(input.tubes)||input.tubes.length!==5)throw Error('Use five bar slots.');const used=new Set();c.tubes=input.tubes.map((t,id)=>{
  const ip=String(t.ip||'').trim();if(ip&&!privateIP(ip)&&!(test&&/^127\.0\.0\.[1-5]$/.test(ip)))throw Error(`Bar ${id+1}: enter a local IPv4 address.`);
  if(ip&&used.has(ip))throw Error('Each bar needs a different IP address.');if(ip)used.add(ip);
  return {id,name:String(t.name||`Bar ${id+1}`).trim().slice(0,30),ip,enabled:t.enabled!==false,group:t.group===1?1:0};
 });}return c;
}
export function selected(config,ids){if(!Array.isArray(ids)||!ids.length||ids.length>5||ids.some(id=>!Number.isInteger(id)||id<0||id>4)||new Set(ids).size!==ids.length)throw Error('Select one or more bars.');const bars=ids.map(id=>config.tubes[id]);if(bars.some(t=>!t.ip||!t.enabled))throw Error('Connect and enable all selected bars first.');return bars;}
export const activeSegments=s=>(s?.seg||[]).filter(s=>Number.isInteger(s.id)&&s.stop>s.start);
export function primarySegment(s){return activeSegments(s).find(x=>x.id===s.mainseg)||activeSegments(s)[0]||{};}
const range=(x,a,b)=>Number.isInteger(x)&&x>=a&&x<=b;
export function validatePatch(p){
 if(!p||typeof p!=='object'||Array.isArray(p)||!Object.keys(p).length)throw Error('Choose a control to change.');
 for(const [k,v] of Object.entries(p)){
  if(['on','rev','mi','o1','o2','o3'].includes(k)){if(typeof v!=='boolean')throw Error(`Invalid ${k}.`);}
  else if(['bri','sx','ix','c1','c2','c3'].includes(k)){if(!range(v,0,k==='c3'?31:255))throw Error(`Invalid ${k}.`);}
  else if(k==='transition'){if(!range(v,0,100))throw Error('Transition must be 0–10 seconds.');}
  else if(['fx','pal'].includes(k)){if(typeof v!=='string'||!v||v.length>120)throw Error(`Invalid ${k}.`);}
  else if(k==='color'){if(!v||!range(v.slot,0,2)||!Array.isArray(v.rgb)||v.rgb.length!==3||!v.rgb.every(x=>range(x,0,255)))throw Error('Choose an RGB color.');}
  else throw Error('Unknown control: '+k);
 }return p;
}
export function payload(p,d){
 validatePatch(p);const out={udpn:{send:false,rgrp:0,nn:true}};
 for(const k of ['on','bri','transition'])if(k in p)out[k]=p[k];
 const seg={};for(const k of ['sx','ix','c1','c2','c3','o1','o2','o3','rev','mi'])if(k in p)seg[k]=p[k];
 for(const [key,list]of [['fx','effects'],['pal','palettes']])if(key in p){const id=d[list].indexOf(p[key]);if(id<0)throw Error(`${d.name}: ${p[key]} is not available.`);seg[key]=id;}
 if(Object.keys(seg).length||p.color){const segments=activeSegments(d.state);if(!segments.length)throw Error(`${d.name}: no active WLED segments. Open WLED to configure the LED strip.`);
  out.seg=segments.map(s=>{const update={id:s.id,...seg};if(p.color){const col=[{},{},{}];const [r,g,b]=p.color.rgb;col[p.color.slot]={r,g,b,w:0};update.col=col;}return update;});
  out.live=false;out.lor=0;
 }return out;
}
export function catalog(devices,key){if(!devices.length||devices.some(d=>!d?.ok))return [];return devices[0][key].filter((name,index,a)=>name&&name!=='RSVD'&&a.indexOf(name)===index&&devices.every(d=>d[key].includes(name)));}
export function captureScene(d){const segments=activeSegments(d.state);if(!segments.length)throw Error(`${d.name}: no active segments to save.`);if(segments.some(s=>!d.effects[s.fx]||!d.palettes[s.pal]))throw Error(`${d.name}: this look uses an effect or custom palette not listed by WLED. Save it in WLED instead.`);return {ip:d.ip,on:!!d.state.on,bri:d.state.bri,transition:d.state.transition??0,segments:segments.map(s=>({id:s.id,fx:d.effects[s.fx],pal:d.palettes[s.pal],col:s.col,on:s.on,bri:s.bri,sx:s.sx,ix:s.ix,c1:s.c1,c2:s.c2,c3:s.c3,o1:s.o1,o2:s.o2,o3:s.o3,rev:s.rev,mi:s.mi}))};}
export function scenePayload(scene,d){
 const p={on:scene.on,bri:scene.bri,transition:scene.transition,live:false,lor:0,udpn:{send:false,rgrp:0,nn:true}};
 if(scene.ip!==d.ip)throw Error('This scene belongs to a previous bar connection. Save a new scene.');
 p.seg=scene.segments.map(s=>{if(!activeSegments(d.state).some(x=>x.id===s.id))throw Error(`${d.name}: segment layout changed. Save a new scene.`);
  const fx=d.effects.indexOf(s.fx),pal=d.palettes.indexOf(s.pal);if(fx<0||pal<0)throw Error(`${d.name}: scene effect or palette is missing.`);
  const out={...s,fx,pal};delete out.ip;return out;
 });return p;
}

import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import {spawnSync} from 'node:child_process';
export const FORMAT='tuberoom-update-v1';
export const FILES=['package.json','server.mjs','engine.mjs','updater.mjs','public/index.html','public/app.js','public/style.css'];
export const LIMIT=2*1024*1024;
const hash=s=>crypto.createHash('sha256').update(s).digest('hex');
const versionOK=v=>typeof v==='string'&&/^\d{1,4}\.\d{1,4}\.\d{1,4}$/.test(v);
export const newer=(a,b)=>{const aa=a.split('.').map(Number),bb=b.split('.').map(Number);for(let i=0;i<3;i++){if(aa[i]!==bb[i])return aa[i]>bb[i];}return false;};
export function readJSON(file,fallback){try{return JSON.parse(fs.readFileSync(file,'utf8'));}catch{return fallback;}}
export function atomicJSON(file,value){const temp=file+'.tmp';fs.writeFileSync(temp,JSON.stringify(value,null,2));fs.renameSync(temp,file);}
export function validateBundle(bundle){
 if(!bundle||bundle.format!==FORMAT||!versionOK(bundle.version)||!Array.isArray(bundle.files))throw Error('This is not a supported TubeRoom update file.');
 if(Buffer.byteLength(JSON.stringify(bundle))>LIMIT)throw Error('Update exceeds the 2 MB limit.');
 const seen=new Set();for(const file of bundle.files){if(!file||!FILES.includes(file.path)||seen.has(file.path))throw Error('Unexpected or duplicate file in the update.');seen.add(file.path);if(typeof file.content!=='string'||!file.content.length||hash(file.content)!==file.sha256)throw Error('Update integrity check failed: '+file.path);}
 if(seen.size!==FILES.length)throw Error('Update is incomplete. No app files have been changed.');
 const pkg=JSON.parse(bundle.files.find(f=>f.path==='package.json').content);if(pkg.name!=='tube-room'||pkg.version!==bundle.version)throw Error('Update version does not match its app package.');
 return {...bundle,notes:String(bundle.notes||'').slice(0,3000)};
}
export function releasePath(data,id){if(!/^(?:\d{1,4}\.){2}\d{1,4}-[a-f0-9]{16}$/.test(id||''))throw Error('Invalid release identifier.');return path.join(data,'releases',id);}
export function pointer(data){return readJSON(path.join(data,'current-release.json'),null);}
export function changePointer(data,value){atomicJSON(path.join(data,'current-release.json'),value);}
export function installBundle(data,bundle,currentVersion){
 bundle=validateBundle(bundle);if(!newer(bundle.version,currentVersion))throw Error('This update is not newer than the installed version.');
 const id=bundle.version+'-'+hash(JSON.stringify(bundle.files)).slice(0,16),dest=releasePath(data,id),stage=dest+'.staging';fs.mkdirSync(path.dirname(dest),{recursive:true});fs.rmSync(stage,{recursive:true,force:true});fs.mkdirSync(stage);
 try{for(const file of bundle.files){const target=path.join(stage,file.path);fs.mkdirSync(path.dirname(target),{recursive:true});fs.writeFileSync(target,file.content);}
  for(const name of ['server.mjs','engine.mjs','updater.mjs','public/app.js']){const check=spawnSync(process.execPath,['--check',path.join(stage,name)],{timeout:5000,encoding:'utf8'});if(check.status!==0)throw Error('Update has a JavaScript syntax error. Your current app was kept.');}
  if(fs.existsSync(dest))fs.rmSync(dest,{recursive:true,force:true});fs.renameSync(stage,dest);
  const old=pointer(data);changePointer(data,{current:id,previous:old?.current||null,pending:true,version:bundle.version});return {version:bundle.version,id};
 }catch(e){fs.rmSync(stage,{recursive:true,force:true});throw e;}
}
export function rollback(data){const p=pointer(data);if(!p?.current)throw Error('There is no installed update to roll back.');changePointer(data,{current:p.previous||null,previous:null,pending:!!p.previous,rolledBack:true});atomicJSON(path.join(data,'update-notice.json'),{message:'The previous version was restored. Your setup was preserved.'});return {ok:true};}
export function updaterInfo(data,version){const pref=readJSON(path.join(data,'update-source.json'),{}),p=pointer(data);return {version,source:pref.url||'',managed:process.env.TUBEROOM_MANAGED==='1',canRollback:!!p?.current,notice:readJSON(path.join(data,'update-notice.json'),{}).message||''};}
export function setSource(data,value){let url=null;if(value){try{url=new URL(value);}catch{throw Error('Enter a valid HTTPS update address.');}if(url.protocol!=='https:'||url.username||url.password||url.hash)throw Error('Updates require an HTTPS address without credentials.');}atomicJSON(path.join(data,'update-source.json'),{url:url?.href||''});}
export async function fetchUpdate(data,version){
 const url=readJSON(path.join(data,'update-source.json'),{}).url;if(!url)throw Error('Online updates are not connected yet. Install an update file below, or connect a publishing source.');
 const res=await fetch(url,{redirect:'error',headers:{Accept:'application/json'},signal:AbortSignal.timeout(20000)});if(!res.ok)throw Error('Could not check updates (HTTP '+res.status+'). Your current app is unchanged.');
 const chunks=[];let bytes=0;for await(const chunk of res.body){bytes+=chunk.length;if(bytes>LIMIT)throw Error('Update download exceeds the size limit.');chunks.push(chunk);}
 const bundle=validateBundle(JSON.parse(Buffer.concat(chunks).toString('utf8')));return {available:newer(bundle.version,version),version:bundle.version,notes:bundle.notes,bundle};
}

const $=id=>document.getElementById(id);
let model,token='',ids=[],page=0,working=false,pendingOff=false,previews={},colorSlot=0,colorTargets=[],sceneTargets=[];
const byId=id=>model?.devices[id],bars=()=>ids.map(id=>model.config.tubes[id]),chosen=()=>ids.map(byId),ready=()=>ids.length>0&&chosen().every(d=>d?.ok),activeSegments=d=>(d?.state?.seg||[]).filter(s=>s.stop>s.start);
const primary=d=>activeSegments(d).find(s=>s.id===d.state.mainseg)||activeSegments(d)[0]||{};
const same=a=>a.length&&a.every(v=>JSON.stringify(v)===JSON.stringify(a[0]))?a[0]:null;
const values=(key,segment=false)=>chosen().flatMap(d=>segment?activeSegments(d).map(s=>s[key]):[d?.state?.[key]]);
const common=key=>!ready()?[]:chosen()[0][key].filter((n,i,a)=>n&&n!=='RSVD'&&a.indexOf(n)===i&&chosen().every(d=>d[key].includes(n)));
const text=(id,value)=>$(id).textContent=value;
